const d=$input.first().json;
if(typeof d.ready!=="boolean") throw new Error("Missing readiness state");
if(!d.ready) return [];
const e=d.text;
if(!e || e.schema_version!==1 || e.kind!=="clip" || e.job_id!==d.job_id || !/^[a-f0-9]{32}$/.test(e.job_id) || !/^[a-f0-9]{32}$/.test(e.attempt_id) || typeof d.task!=="string" || d.task.length>8192 || !Number.isFinite(e.model_deadline) || !Number.isFinite(e.expires_at) || e.expires_at<=Date.now()/1000 || e.model_deadline>=e.expires_at || !Number.isSafeInteger(d.max_payload_bytes) || d.max_payload_bytes<1024) throw new Error("Invalid original text attempt");
const task=JSON.parse(d.task);
if(Object.keys(task).length!==Object.keys(e).length || Object.keys(e).some(key=>JSON.stringify(task[key])!==JSON.stringify(e[key]))) throw new Error("Text task identity changed");
return [{json:d}];

const job=$("Require leased job").first().json;
const native=$input.first().json;
if(!native || typeof native!=="object" || Array.isArray(native)) throw new Error("Invalid native text response");
const failed=Object.prototype.hasOwnProperty.call(native,"error");
let receipt_json=typeof native.result==="string"?native.result:(failed && typeof native.stdout==="string"?native.stdout:null);
const native_failure=failed?{timed_out:native.timedOut===true,exit_code:Number.isInteger(native.exitCode)&&native.exitCode>=-255&&native.exitCode<=255?native.exitCode:null}:null;
const payload={envelope:job.text,receipt_json,native_failure};
// If string escaping exceeds the transport budget, the coordinator reads the
// fsynced original result.json instead. No usage or JSON is truncated.
if(Buffer.byteLength(JSON.stringify(payload),"utf8")>job.max_payload_bytes) payload.receipt_json=null;
const raw=JSON.stringify(payload);
if(Buffer.byteLength(raw,"utf8")>job.max_payload_bytes) throw new Error("Text transport budget exceeded");
const stdinB64=Buffer.from(raw,"utf8").toString("base64");
if(!/^[A-Za-z0-9+/=]+$/.test(stdinB64)) throw new Error("Invalid transport encoding");
return [{json:{stdinB64}}];

const native=$input.first().json;
const e=$("Require visual review").first().json.visual;
if(!native || typeof native!=="object" || Array.isArray(native)) throw new Error("Invalid native visual response");
const failed=Object.prototype.hasOwnProperty.call(native,"error");
let result=typeof native.result==="string"?native.result:null;
if(result===null && failed && typeof native.stdout==="string") {
 try { const candidate=JSON.parse(native.stdout); if(candidate && candidate.envelope) result=native.stdout; } catch {}
}
if(result===null) {
 const timedOut=failed && native.timedOut===true;
 result=JSON.stringify({envelope:e,outcome:timedOut?"timeout":"failed",decision:null,usage_observed:false,usage:null,
  model:{provider:"deepseek-official",model:"deepseek-flash"},observed_at:new Date().toISOString(),
  failure:{category:timedOut?"timeout":"model_failed",code:timedOut?"native_timeout":"native_receipt_missing",status:null,retry_after_ms:null}});
}
if(Buffer.byteLength(result,"utf8")>262144) throw new Error("Visual receipt transport exceeded");
const receipt=JSON.parse(result);
if(JSON.stringify(receipt.envelope)!==JSON.stringify(e)) throw new Error("Native visual envelope changed");
// Keep original UTF-8 bytes: strict coordinator parsing owns authorization.
const stdinB64=Buffer.from(result,"utf8").toString("base64");
if(!/^[A-Za-z0-9+/=]+$/.test(stdinB64)) throw new Error("Invalid visual transport");
return [{json:{stdinB64}}];

const raw=$input.first().json.stdout;
if(typeof raw!=="string" || Buffer.byteLength(raw,"utf8")>1048576) throw new Error("Invalid operational health output");
const d=JSON.parse(raw), h=d.health;
if(!h || typeof h.actionable!=="boolean" || !Array.isArray(h.issues)) throw new Error("Missing operational health contract");
if(h.actionable) throw new Error("CLIPPING_OPERATIONAL_FAILURE "+JSON.stringify({state:h.state,issues:h.issues.slice(0,20)}));
return [{json:{state:d.state,health:h}}];

const d=$input.first().json;
if(typeof d.ready!=="boolean") throw new Error("Missing readiness state");
const action=d.action_result || d;
return !d.ready && action.state!=="visual_pending" ? [{json:d}] : [];
